void BOARD_InitBootPins(void) {
    BOARD_InitPins();
    BOARD_ECAT_MDIO_InitPins();
    BOARD_InitPWM();
    BOARD_InitENC();
    BOARD_Port0_MII_InitPins();
    BOARD_Port1_MII_InitPins();
    BOARD_ECAT_I2C_InitPins();
    BOARD_InitADC();
}

